import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

/** Controller desk D4c — the seam between `@dcortex/canvas-ui`'s stylesheet and this app's theme tokens.
 *
 * canvas-ui ships geometry and colour as `var(--token)`; the tokens themselves live here, in both themes. A
 * `var(--x)` with no `--x` resolves to nothing and CSS says nothing about it — the modal backdrop shipped
 * transparent for exactly that reason (`--bg-overlay` was written, never defined), and the case pane's text input
 * shipped with no ground (`--surface-input`). This is the origin of that class of defect, so the check lives here. */

const here = dirname(fileURLToPath(import.meta.url));
const read = (rel: string) => readFileSync(join(here, rel), "utf8");
const tokens = read("./tokens.css");
const deskCss = read("../../../../platform/canvas-ui/styles.css");

/** Tokens a component sets inline on the element itself, so they are never expected in the theme. */
const INLINE = new Set(["--labelW", "--hourW"]);

const declared = (css: string) => new Set([...css.matchAll(/(--[A-Za-z0-9-]+)\s*:/g)].map((m) => m[1]!));
const consumed = (css: string) => new Set([...css.matchAll(/var\((--[A-Za-z0-9-]+)/g)].map((m) => m[1]!));

const block = (selector: string) => {
  const at = tokens.indexOf(selector);
  expect(at, `${selector} block is missing from tokens.css`).toBeGreaterThanOrEqual(0);
  return tokens.slice(at, tokens.indexOf("}", at));
};
const ROOT = ':root,\nhtml[data-theme="dark"]';
const LIGHT = 'html[data-theme="light"]';

describe("canvas theme tokens", () => {
  const needed = [...consumed(deskCss)].filter((t) => !INLINE.has(t) && !declared(deskCss).has(t)).sort();

  it("the desk stylesheet consumes only tokens this app declares", () => {
    expect(needed.length).toBeGreaterThan(20); // the check is worthless if the regex stops matching
    expect(needed.filter((t) => !declared(tokens).has(t))).toEqual([]);
  });

  it("the base block declares every one of them, so the light theme only ever overrides", () => {
    const base = declared(block(ROOT));
    expect(needed.filter((t) => !base.has(t))).toEqual([]);
    expect([...declared(block(LIGHT))].filter((t) => !base.has(t))).toEqual([]);
  });
});

