    expect(radar).toMatch(/html\[data-theme="light"\]\s*\.radar-screen\s*\{/);
    const lightAt = radar.indexOf('html[data-theme="light"] .radar-screen');
    const lightBlock = radar.slice(lightAt, radar.indexOf("}", lightAt));
    for (const token of ["--radar-ground", "--radar-disc", "--radar-panel-bg", "--radar-ink", "--radar-crt"]) {
      expect(lightBlock, `light Radar must override ${token}`).toMatch(new RegExp(`${token}\\s*:`));
